function Metric({icon:Icon,label,value,detail,positive}:{icon:typeof WalletCards;label:string;value:string;detail:string;positive?:boolean}){useLanguage();return <div className="metric"><div className="metric-top"><span>{t(label)}</span><i><Icon size={19}/></i></div><strong>{value}</strong><small className={positive?"positive":""}>{t(detail)}</small></div>}
