function ThermalReceipt(props:{sale:RecentSale|null;paymentLabel:(value:string)=>string;storeLine:string}){useLanguage();return <Receipt {...props}/>}

function BarcodeGraphic({value}:{value:string}){useLanguage();const L=["0001101","0011001","0010011","0111101","0100011","0110001","0101111","0111011","0110111","0001011"],G=["0100111","0110011","0011011","0100001","0011101","0111001","0000101","0010001","0001001","0010111"],R=["1110010","1100110","1101100","1000010","1011100","1001110","1010000","1000100","1001000","1110100"],parity=["LLLLLL","LLGLGG","LLGGLG","LLGGGL","LGLLGG","LGGLLG","LGGGLL","LGLGLG","LGLGGL","LGGLGL"];let digits=value.replace(/\D/g,"");if(digits.length===12){const sum=digits.split("").reduce((s,d,i)=>s+Number(d)*(i%2===0?1:3),0);digits+=String((10-sum%10)%10)}if(digits.length!==13)return <div className="barcode-fallback">{value||t("Barkod yoxdur")}</div>;const left=digits.slice(1,7).split("").map((d,i)=>(parity[Number(digits[0])][i]==="L"?L:G)[Number(d)]).join(""),right=digits.slice(7).split("").map(d=>R[Number(d)]).join(""),bits=`101${left}01010${right}101`;return <svg className="ean-barcode" viewBox="0 0 95 60" role="img" aria-label={`EAN-13 ${digits}`}>{bits.split("").map((bit,i)=>bit==="1"?<rect key={i} x={i} y="0" width="1" height={(i<3||(i>=45&&i<50)||i>=92)?50:44}/>:null)}<text x="47.5" y="58" textAnchor="middle" fontSize="7">{digits}</text></svg>}

function BarcodeLabel({product}:{product:Product|null}){useLanguage();if(!product)return null;return <section className="print-sheet barcode-label"><strong>BirKassa</strong><h2>{product.name}</h2><BarcodeGraphic value={product.barcode}/><div><span>{product.sku}</span><b>{money(product.price)}</b></div></section>}

