  const total=Math.max(0,Number((subtotal-discount+deliveryFee).toFixed(2))),selectedCustomer=customers.find(x=>x.id===customerId);
  async function loadOptions(){const response=await fetch("/api/pos-options",{cache:"no-store"});if(response.ok){const data=await response.json() as {customers:PosCustomer[];held:HeldReceipt[];requireManagerVoid?:boolean;maxDiscountPercent?:number};setCustomers(data.customers);setHeld(data.held);setVoidNeedsPin(data.requireManagerVoid!==false);setMaxDiscount(Number(data.maxDiscountPercent??10))}}useEffect(()=>{void loadOptions()},[]);
  useEffect(()=>{if(!incomingOrder)return;restore(Object.fromEntries(incomingOrder.items.map((item:any)=>[String(item.productId)+(item.optionId?":"+item.optionId:""),Number(item.quantity)])));setLockedOrder(incomingOrder);setDiscount(Math.max(0,Number((incomingOrder.items.reduce((s:number,i:{unitPrice:number;quantity:number})=>s+Number(i.unitPrice)*Number(i.quantity),0)+Number(incomingOrder.deliveryFee||0)-Number(incomingOrder.total)).toFixed(2))));setCustomerId(incomingOrder.customerId||"");setSalesOrderId(incomingOrder.id);setOrderNo(incomingOrder.order_no);setMessage(`${incomingOrder.order_no} kassada açıldı. Stok ödənişdən sonra azalacaq`);onOrderLoaded()},[incomingOrder]);
  function matchBarcode(raw:string){if(salesOrderId){setMessage("Sifariş məhsullarını dəyişmək olmaz.");return;}const normalized=raw.trim().toLocaleLowerCase("az");if(scanRef.current)scanRef.current.value="";setQuery("");if(!normalized)return;const product=(products as Product[]).find((p:Product)=>[p.barcode,p.sku,...(p.barcodes||[]).map(b=>b.barcode)].filter(Boolean).some(value=>String(value).trim().toLocaleLowerCase("az")===normalized));if(product){add(product);setMessage(`${product.name} əlavə olundu`);scanRef.current?.focus()}else setMessage("Bu barkodla məhsul tapılmadı")}
  useEffect(()=>{scanRef.current?.focus();function keep(){if(document.querySelector("[role='dialog']"))return;const active=document.activeElement;if(active&&(active.tagName==="INPUT"||active.tagName==="TEXTAREA")&&active!==scanRef.current)return;scanRef.current?.focus()}const timer=window.setInterval(keep,700);return()=>window.clearInterval(timer)},[]);
  useEffect(()=>{let buffer="",last=0;function onKey(event:KeyboardEvent){const target=event.target as HTMLElement|null;const dialog=document.querySelector("[role='dialog']");const typingElsewhere=Boolean(target&&(target.tagName==="INPUT"||target.tagName==="TEXTAREA"||target.isContentEditable)&&target!==scanRef.current);if(!dialog&&!typingElsewhere&&event.key.length===1&&!event.ctrlKey&&!event.metaKey&&!event.altKey){const now=Date.now();if(now-last>120)buffer="";buffer+=event.key;last=now;if(target!==scanRef.current){event.preventDefault();setQuery(buffer)}}if(!dialog&&!typingElsewhere&&(event.key==="Enter"||event.key==="Tab")&&buffer.length>=4&&Date.now()-last<500&&target!==scanRef.current){event.preventDefault();matchBarcode(buffer);buffer=""}if(typingElsewhere&&!["F2","F4","F5","F6","F7","F8","F9","F10"].includes(event.key))return;if(event.key==="F2"){event.preventDefault();scanRef.current?.focus()}if(event.key==="F4"&&cartRows.length){event.preventDefault();void holdReceipt()}if(event.key==="F5"&&cartRows.length){event.preventDefault();!salesOrderId&&setDiscountOpen(true)}if(event.key==="F6"){event.preventDefault();setCustomerOpen(true)}if(event.key==="F7"){event.preventDefault();setHeldOpen(true)}if(event.key==="F8"&&cartRows.length){event.preventDefault();void pay("cash")}if(event.key==="F9"&&cartRows.length){event.preventDefault();void pay("card")}if(event.key==="F10"&&cartRows.length){event.preventDefault();setMixedOpen(true)}}window.addEventListener("keydown",onKey,true);return()=>window.removeEventListener("keydown",onKey,true)},[cartRows.length,scanRef,discount,customerId,salesOrderId,products]);
  function scan(event:React.KeyboardEvent<HTMLInputElement>){if(event.key!=="Enter"&&event.key!=="Tab")return;event.preventDefault();matchBarcode(event.currentTarget.value)}
  async function pay(paymentMethod:"cash"|"card"|"mixed",cashAmount?:number,cardAmount?:number,pin=managerPin){
    const percent=subtotal?discount/subtotal*100:0;
    if(percent>maxDiscount&&!pin&&!(salesOrderId&&lockedOrder?.source==="catalog")){setPendingPay({method:paymentMethod,cash:cashAmount,card:cardAmount});setPinOpen(true);return}
    return complete(paymentMethod,cashAmount,cardAmount,pin)
  }
  async function complete(paymentMethod:"cash"|"card"|"mixed",cashAmount?:number,cardAmount?:number,pin=managerPin){
    if(!cartRows.length||saving)return;setSaving(true);setMessage("");
    try{const response=await fetch("/api/sales",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({paymentMethod,cashAmount,cardAmount,discount,customerId:customerId||null,salesOrderId:salesOrderId||null,managerPin:pin,buyerName,items:cartRows.map((p:Product)=>({productId:String(p.baseProductId||p.id),optionId:p.optionId||null,quantity:cart[String(p.id)]}))})});const result=await response.json() as {error?:string;receiptNo?:string;total?:number;receipt?:RecentSale};if(!response.ok){setMessage(result.error||"Satış tamamlanmadı");return}setLastReceipt(result.receiptNo||"Yeni çek");setCompletedSale(result.receipt||null);setBuyerName("");setMessage(`${result.receiptNo} · ${money(result.total||total)} ödəniş tamamlandı`);setDiscount(0);setCustomerId("");setSalesOrderId("");setOrderNo("");setManagerPin("");setMixedOpen(false);await onCompleted()}catch{setMessage("Serverlə əlaqə qurulmadı")}finally{setSaving(false)}
  }
