  async function restoreHeld(item:HeldReceipt){restore(Object.fromEntries(item.items.map(x=>[String(x.productId)+(x.optionId?":"+x.optionId:""),Number(x.quantity)])));setDiscount(item.discount);setCustomerId(item.customerId||"");await fetch("/api/pos-options",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({action:"delete_held",heldId:item.id})});setHeldOpen(false);await loadOptions();setMessage("Gözləyən çek bərpa edildi")}
